// Providers: which coding agents exist on this machine, how each one finds skills, and what the user decided about them.
// The catalog (data/providers.json, generated by tools/gen-providers.py) lists agents that read user-level skills.
// Detection looks for the agent's command or its own config folder; the user can override every decision, and add their own.
#include "store.h"

#include <QDir>
#include <QFile>
#include <QFileInfo>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QProcess>
#include <QRegularExpression>
#include <QSaveFile>
#include <QStandardPaths>

namespace hub {

namespace {

// "~", "${VAR:-default}" and "$VAR" -> absolute path ("" stays "")
QString expandPath(QString s) {
    if (s.trimmed().isEmpty()) return {};
    static const QRegularExpression braced(QStringLiteral(R"(\$\{([A-Za-z_][A-Za-z0-9_]*)(?::-([^}]*))?\})"));
    QRegularExpressionMatch m;
    int guard = 0;
    while ((m = braced.match(s)).hasMatch() && ++guard < 8) {
        QString v = qEnvironmentVariable(m.captured(1).toUtf8().constData());
        if (v.trimmed().isEmpty()) v = expandPath(m.captured(2));
        s.replace(m.capturedStart(), m.capturedLength(), v);
    }
    if (s == QLatin1String("~") || s.startsWith(QLatin1String("~/"))) s = QDir::homePath() + s.mid(1);
    return QDir::cleanPath(s);
}

QStringList expandAll(const QJsonArray &a) {
    QStringList out;
    for (const QJsonValue &v : a) {
        const QString e = expandPath(v.toString());
        if (!e.isEmpty()) out << e;
    }
    return out;
}

QStringList searchDirs() {
    if (qEnvironmentVariableIsSet("SKILLHUB_BIN_PATH"))  // tests
        return qEnvironmentVariable("SKILLHUB_BIN_PATH").split(QDir::listSeparator(), Qt::SkipEmptyParts);
    QStringList dirs = qEnvironmentVariable("PATH").split(QDir::listSeparator(), Qt::SkipEmptyParts);
    const QString h = QDir::homePath();
    // a service or an app started from the desktop has a short PATH: also look where installers put commands
    for (const char *d : {"/.local/bin", "/.cargo/bin", "/.bun/bin", "/.npm-global/bin", "/go/bin", "/.deno/bin", "/.local/share/pnpm",
                          "/.claude/local", "/.opencode/bin"})
        dirs << h + QLatin1String(d);
#if defined(Q_OS_MACOS)
    dirs << QStringLiteral("/opt/homebrew/bin") << QStringLiteral("/usr/local/bin");
#elif defined(Q_OS_WIN)
    const QString appData = qEnvironmentVariable("APPDATA");
    if (!appData.isEmpty()) dirs << appData + QStringLiteral("/npm");
    dirs << h + QStringLiteral("/scoop/shims");
#endif
    return dirs;
}

// finds `name` the way a shell does (on Windows: with .exe/.cmd/.bat from PATHEXT)
QString findCommand(const QString &name) { return QStandardPaths::findExecutable(name, searchDirs()); }

QString shown(const QString &path) {
    const QString h = QDir::homePath();
    return path == h || path.startsWith(h + QLatin1Char('/')) ? QStringLiteral("~") + path.mid(h.size()) : path;
}

QString slugify(const QString &s) {
    QString out;
    for (const QChar c : s.toLower()) {
        if (c.isLetterOrNumber()) out += c;
        else if (!out.isEmpty() && !out.endsWith(QLatin1Char('-'))) out += QLatin1Char('-');
    }
    while (out.endsWith(QLatin1Char('-'))) out.chop(1);
    return out;
}

QJsonObject readJson(const QString &path) {
    QFile f(path);
    return f.open(QIODevice::ReadOnly) ? QJsonDocument::fromJson(f.readAll()).object() : QJsonObject();
}

bool writeJson(const QString &path, const QJsonObject &o) {
    QDir().mkpath(QFileInfo(path).absolutePath());
    QSaveFile f(path);
    if (!f.open(QIODevice::WriteOnly)) return false;
    f.write(QJsonDocument(o).toJson(QJsonDocument::Indented));
    return f.commit();
}

AgentDef fromJson(const QJsonObject &o, bool custom) {
    AgentDef a;
    a.id = o.value(QStringLiteral("id")).toString();
    a.label = o.value(QStringLiteral("label")).toString();
    a.mode = o.value(QStringLiteral("mode")).toString(QStringLiteral("link"));
    a.dir = expandPath(o.value(QStringLiteral("dir")).toString());
    a.linked = a.mode == QLatin1String("link");
    a.extraDirs = expandAll(o.value(QStringLiteral("extraDirs")).toArray());
    for (const QJsonValue &v : o.value(QStringLiteral("ignore")).toArray()) a.ignore << v.toString();
    for (const QJsonValue &v : o.value(QStringLiteral("bins")).toArray()) a.bins << v.toString();
    a.detect = expandAll(o.value(QStringLiteral("detect")).toArray());
    a.configFile = expandPath(o.value(QStringLiteral("configFile")).toString());
    a.custom = custom;
    return a;
}

}  // namespace

QString Store::providersFile() const {
    if (qEnvironmentVariableIsSet("SKILLHUB_CONFIG"))  // tests
        return QDir::cleanPath(qEnvironmentVariable("SKILLHUB_CONFIG")) + QStringLiteral("/providers.json");
    return QStandardPaths::writableLocation(QStandardPaths::GenericConfigLocation) + QStringLiteral("/skillhub/providers.json");
}

void Store::reloadProviders() {
    QVector<AgentDef> all;
    const QJsonObject catalog = readJson(QStringLiteral(":/data/providers.json"));
    for (const QJsonValue &v : catalog.value(QStringLiteral("providers")).toArray()) {
        AgentDef a = fromJson(v.toObject(), false);
        if (!a.id.isEmpty()) all.push_back(a);
    }
    const QJsonObject user = readJson(providersFile());
    for (const QJsonValue &v : user.value(QStringLiteral("custom")).toArray()) {
        AgentDef a = fromJson(v.toObject(), true);
        if (!a.id.isEmpty()) all.push_back(a);
    }
    const QJsonObject overrides = user.value(QStringLiteral("overrides")).toObject();

    agents_.clear();
    for (AgentDef &a : all) {
        for (const QString &b : a.bins) {
            const QString p = findCommand(b);
            if (!p.isEmpty()) {
                a.detected = true;
                a.detectedBy = QStringLiteral("command `%1`").arg(b);
                break;
            }
        }
        if (!a.detected) {
            for (const QString &d : a.detect) {
                if (QFileInfo::exists(d)) {
                    a.detected = true;
                    a.detectedBy = QStringLiteral("folder %1").arg(shown(d));
                    break;
                }
            }
        }
        if (a.custom) {
            a.detected = true;
            a.detectedBy = QStringLiteral("added by you");
        }
        const QString o = overrides.value(a.id).toString();
        a.managed = o == QLatin1String("on") ? true : o == QLatin1String("off") ? false : a.detected;
        if (a.managed) agents_.push_back(a);
    }
    providers_ = all;
}

static bool saveUser(const Store &s, const QJsonObject &user) { return writeJson(s.providersFile(), user); }

bool Store::setProviderManaged(const QString &id, bool on, QString *err) {
    const AgentDef *p = nullptr;
    for (const AgentDef &a : providers_)
        if (a.id == id) p = &a;
    if (!p) {
        if (err) *err = QStringLiteral("unknown provider: %1").arg(id);
        return false;
    }
    QJsonObject user = readJson(providersFile());
    QJsonObject ov = user.value(QStringLiteral("overrides")).toObject();
    if (on == p->detected) ov.remove(id);  // same as the automatic decision: no override needed
    else ov.insert(id, on ? QStringLiteral("on") : QStringLiteral("off"));
    user.insert(QStringLiteral("version"), 1);
    user.insert(QStringLiteral("overrides"), ov);
    if (!saveUser(*this, user)) {
        if (err) *err = QStringLiteral("cannot write %1").arg(providersFile());
        return false;
    }
    reloadProviders();
    return true;
}

QString Store::addCustomProvider(const QString &labelIn, const QString &dirIn, const QString &modeIn, QString *err) {
    const QString label = labelIn.trimmed().left(40);
    const QString mode = modeIn == QLatin1String("native") ? QStringLiteral("native") : QStringLiteral("link");
    const QString dir = expandPath(dirIn.trimmed());
    const QString slug = slugify(label);
    const QString home = QDir::homePath();
    auto fail = [&](const QString &m) { if (err) *err = m; return QString(); };
    if (label.isEmpty() || slug.isEmpty()) return fail(QStringLiteral("give the agent a name"));
    if (dir.isEmpty() || !QDir::isAbsolutePath(dir)) return fail(QStringLiteral("the skills folder must be an absolute path (or start with ~)"));
    if (QDir(dir).isRoot() || dir == home || home.startsWith(dir + QLatin1Char('/'))) return fail(QStringLiteral("that folder is too broad to manage"));
    if (mode == QLatin1String("link") && (dir == central_ || dir.startsWith(central_ + QLatin1Char('/'))))
        return fail(QStringLiteral("the agent's own folder cannot be the shared folder (choose \"reads the shared folder\")"));
    const QString id = QStringLiteral("custom-") + slug;
    for (const AgentDef &a : providers_)
        if (a.id == id) return fail(QStringLiteral("an agent called \"%1\" already exists").arg(label));

    QJsonObject o;
    o.insert(QStringLiteral("id"), id);
    o.insert(QStringLiteral("label"), label);
    o.insert(QStringLiteral("mode"), mode);
    if (mode == QLatin1String("link")) {
        o.insert(QStringLiteral("dir"), dir);
    } else {
        o.insert(QStringLiteral("dir"), central_);
        o.insert(QStringLiteral("extraDirs"), QJsonArray{dir});  // its own folder: scanned for strays to adopt
    }
    QJsonObject user = readJson(providersFile());
    QJsonArray custom = user.value(QStringLiteral("custom")).toArray();
    custom.append(o);
    user.insert(QStringLiteral("version"), 1);
    user.insert(QStringLiteral("custom"), custom);
    if (!saveUser(*this, user)) return fail(QStringLiteral("cannot write %1").arg(providersFile()));
    reloadProviders();
    return id;
}

bool Store::removeCustomProvider(const QString &id) {
    QJsonObject user = readJson(providersFile());
    QJsonArray custom = user.value(QStringLiteral("custom")).toArray(), keep;
    bool found = false;
    for (const QJsonValue &v : custom) {
        if (v.toObject().value(QStringLiteral("id")).toString() == id) found = true;
        else keep.append(v);
    }
    if (!found) return false;
    QJsonObject ov = user.value(QStringLiteral("overrides")).toObject();
    ov.remove(id);
    user.insert(QStringLiteral("custom"), keep);
    user.insert(QStringLiteral("overrides"), ov);
    const bool ok = saveUser(*this, user);
    reloadProviders();
    return ok;
}

// ---- config-mode wiring (Antigravity lists extra skill folders in ~/.gemini/config/skills.json) ---------------------

bool Store::providerWired(const AgentDef &a) const {
    if (a.mode != QLatin1String("config") || a.configFile.isEmpty()) return true;
    const QJsonArray arr = readJson(a.configFile).value(QStringLiteral("entries")).toArray();
    for (const QJsonValue &v : arr)
        if (v.toObject().value(QStringLiteral("path")).toString() == central_) return true;
    return false;
}

bool Store::wiringOk() const {
    for (const AgentDef &a : agents_)
        if (!providerWired(a)) return false;
    return true;
}

bool Store::ensureProviderConfigs(bool *changed) {
    if (changed) *changed = false;
    bool ok = true;
    for (const AgentDef &a : agents_) {
        if (a.mode != QLatin1String("config") || a.configFile.isEmpty() || providerWired(a)) continue;
        QJsonObject root = readJson(a.configFile);
        QJsonArray entries = root.value(QStringLiteral("entries")).toArray();
        QJsonObject e;
        e.insert(QStringLiteral("path"), central_);  // absolute path: the tool does not expand "~/" here
        entries.append(e);
        root.insert(QStringLiteral("entries"), entries);
        if (writeJson(a.configFile, root)) {
            emit log(QStringLiteral("registered %1 in %2").arg(central_, a.configFile));
            if (changed) *changed = true;
        } else {
            emit log(QStringLiteral("FAILED to write %1").arg(a.configFile));
            ok = false;
        }
    }
    return ok;
}

// ---- stray watcher paths -------------------------------------------------------------------------------------------------

QStringList Store::watchDirs() const {
    QStringList dirs;
    for (const AgentDef &a : agents_) {
        QStringList own = a.extraDirs;
        if (a.linked) own.prepend(a.dir);
        for (const QString &d : own)
            if (!d.isEmpty() && d != central_ && !dirs.contains(d)) dirs << d;
    }
    return dirs;
}

bool Store::watcherStale() const {
    QFile f(QDir::homePath() + QStringLiteral("/.config/systemd/user/skillhub-adopt.path"));
    if (!f.open(QIODevice::ReadOnly)) return false;
    QStringList have;
    for (const QString &l : QString::fromUtf8(f.readAll()).split(QLatin1Char('\n')))
        if (l.startsWith(QLatin1String("PathChanged="))) have << l.mid(12);
    QStringList want = watchDirs();
    have.sort();
    want.sort();
    return !want.isEmpty() && have != want;
}

bool Store::syncWatcher() {
    if (!watcherStale()) return false;
    QString err;
    const bool ok = installUnits(false, true, &err);
    emit log(ok ? QStringLiteral("updated the stray watcher for the agents on this machine") : QStringLiteral("FAILED to update the stray watcher: ") + err);
    return ok;
}

}  // namespace hub
